import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 118 What were you doing?","description":"学习 过去进行时，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 118 What were you doing?","description":"学习 过去进行时，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 过去进行时，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 117 Tommy's breakfast","link":"/life/english/new-concept/book-1/unit-05/lesson-117"},"next":{"text":"第一册：英语初阶 · Lesson 119 A true story","link":"/life/english/new-concept/book-1/unit-05/lesson-119"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 117 Tommy's breakfast","link":"/life/english/new-concept/book-1/unit-05/lesson-117"},"next":{"text":"第一册：英语初阶 · Lesson 119 A true story","link":"/life/english/new-concept/book-1/unit-05/lesson-119"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-118.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-118.md"}`),o={name:"life/english/new-concept/book-1/unit-05/lesson-118.md"};function s(r,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第一册-英语初阶-·-lesson-118-what-were-you-doing" tabindex="-1">第一册：英语初阶 · Lesson 118 What were you doing? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-118-what-were-you-doing" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 118 What were you doing?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-117">配套课 Lesson 117</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>描述过去某一时刻正在进行的活动 本课要掌握过去进行时，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>breakfast</td><td>/ˈbrekfəst/</td><td>n.</td><td>早餐</td><td>have breakfast</td></tr><tr><td>while</td><td>/waɪl/</td><td>conj.</td><td>当……期间</td><td>while I was reading</td></tr><tr><td>ring</td><td>/rɪŋ/</td><td>v.</td><td>响铃</td><td>the phone rang</td></tr><tr><td>spill</td><td>/spɪl/</td><td>v.</td><td>洒出</td><td>spill some milk</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>was cooking — 当时正在做饭</li><li>when the phone rang — 电话响起这一事件</li></ul><h2 id="语法讲解-过去进行时" tabindex="-1">语法讲解：过去进行时 <a class="header-anchor" href="#语法讲解-过去进行时" aria-label="Permalink to &quot;语法讲解：过去进行时&quot;">​</a></h2><p>过去进行时由 was/were + 动词 ing 构成，常描绘过去某时的背景动作。一般过去时可表达期间发生的较短事件，如 was cooking when the phone rang。when 可以引出事件，while 常引出持续背景，但应看从句的实际意义，不能把两个词与某一种时态死绑。过去进行时不保证动作最终完成。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>They were waiting outside at eight yesterday.</p></blockquote><p>昨天八点时他们正在外面等候。</p><p>Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>过去背景用 was/were，不用现在的 am/is/are；短事件不一定也要写进行时。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“They were waiting outside at eight yesterday.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>They were waiting outside at eight yesterday. I was making breakfast when the lights went out.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“描述过去某一时刻正在进行的活动”写两至三句，再读给同伴听。至少使用一次过去进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。 Was making 描写过去背景动作；when 引出的 went out 表停电事件。两者形成持续背景与突发事件的对照。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 be：They ___ waiting at eight yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 按本课规则判断：过去进行时由 was/were + 动词 ing 构成，常描绘过去某时的背景动作。一般过去时可表达期间发生的较短事件，如 was cooking when the phone rang。when 可以引出事件，while 常引出持续背景，但应看从句的实际意义，不能把两个词与某一种时态死绑。过去进行时不保证动作最终完成。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“昨天八点时他们正在外面等候。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They were waiting outside at eight yesterday.</p><p><strong>解析：</strong> Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：I was making breakfast when the lights went out.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 停电时我正在做早饭。</p><p><strong>解析：</strong> Was making 描写过去背景动作；when 引出的 went out 表停电事件。两者形成持续背景与突发事件的对照。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去进行时。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-117">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-119">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
